```python
class Solution:
    def generateParenthesis(self, n):
        ans = []
        def visit(s, opened, closed):
            if len(s) == n * 2:
                ans.append(s)
                return
            if opened < n:
                visit(s + '(', opened + 1, closed)
            if closed < opened:
                visit(s + ')', opened, closed + 1)
        visit('', 0, 0)
        return ans
```

