```python
class Solution:
    def partition(self, s):
        ans = []
        def visit(start, path):
            if start == len(s):
                ans.append(path[:])
                return
            for end in range(start + 1, len(s) + 1):
                part = s[start:end]
                if part == part[::-1]:
                    path.append(part)
                    visit(end, path)
                    path.pop()
        visit(0, [])
        return ans
```

